+Usage? _usableUsage(Message message) {
+  if (message case AssistantMessage(:final stopReason, :final usage)) {
+    if (stopReason != StopReason.aborted &&
+        stopReason != StopReason.error &&
+        observedContextTokens(usage) > 0) {
