      item,
      stopwatch,
      'unknown a2a server "$serverName" — available: $available',
    );
  }
  onProgress?.call(index, id, TaskSpawnPhase.running);
  if (subagentManager != null) {
    await subagentManager!.register(
      id: id,
      name: taskItemNameBase(item),
      agentType: 'a2a:$serverName',
      task: item.task,
    );

