      smolModel != null &&
      (smolModel.provider != mainModel.provider ||
          smolModel.id != mainModel.id);
  return CompactionHostWiring(
    window: window,
    conversationWindow: conversation > 0 ? conversation : 0,
    settings:
        settingsOverride ??
        CompactionSettings.forWindow(conversation > 0 ? conversation : 0),
