  if (subagentManager != null) {
    for (final tool in subagentMonitoringTools(
      manager: subagentManager,
      currentSubagentId: currentSubagentId,
    ).where((t) => childInjectedToolNames.contains(t.name))) {
      toolRegistry.register(tool);
