  Stopwatch stopwatch,
  CancelToken? cancelToken,
  TaskSpawnProgressCallback? onProgress,
) async {
  final manager = a2aManager;
  if (manager == null || manager[serverName] == null) {
    final available =
        manager?.servers.keys.join(', ') ?? 'a2a not configured';
    return _failure(
      index,
