import 'package:flutter_agent_harness/flutter_agent_harness.dart';

int legacyReserve(int w) {
  var r = 16384; // min(16384, max(1024, w ~/ 4))
  final q = w ~/ 4;
  final capped = q > 1024 ? q : 1024;
  if (capped < r) r = capped;
  if (r >= w ~/ 2) r = (w ~/ 4) > 128 ? (w ~/ 4) : 128;
  return r;
